package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.List; import java.util.Optional; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2ARequestRepository implements A2ARequestRepository { private final A2ARequestDao dao; private final A2APersistenceConverter c; public MybatisA2ARequestRepository(A2ARequestDao d,A2APersistenceConverter c){dao=d;this.c=c;} public A2ARequest save(A2ARequest v){dao.upsert(c.toPo(v));return findById(v.getTenantId(),v.getRequestId()).orElseGet(()->findByIdempotencyKey(v.getTenantId(),v.getIdempotencyKey()).orElse(v));} public A2ARequest saveExpectedVersion(A2ARequest v,long expectedVersion){if(dao.updateExpectedVersion(c.toPo(v),expectedVersion)!=1)throw new IllegalStateException("RESOURCE_VERSION_CONFLICT");return findById(v.getTenantId(),v.getRequestId()).orElseThrow();} public Optional<A2ARequest> findById(String t,String id){return Optional.ofNullable(dao.findById(t,id)).map(c::toDomain);} public Optional<A2ARequest> findByIdempotencyKey(String t,String k){return k==null?Optional.empty():Optional.ofNullable(dao.findByIdempotencyKey(t,k)).map(c::toDomain);} public Optional<A2ARequest> findByChildTask(String t,String id){return id==null?Optional.empty():Optional.ofNullable(dao.findByChildTask(t,id)).map(c::toDomain);} public List<A2ARequest> findByRootTask(String t,String id,int n){return dao.findByRootTask(t,id,cap(n)).stream().map(c::toDomain).toList();} public List<A2ARequest> findBySourceTask(String t,String id,int n){return dao.findBySourceTask(t,id,cap(n)).stream().map(c::toDomain).toList();} public List<A2ARequest> search(String t,String status,String text,int n){return dao.search(t,status,text,cap(n)).stream().map(c::toDomain).toList();} public String mode(){return "MYBATIS";} private int cap(int n){return Math.max(1,Math.min(n,1000));} }
